const s=$getWorkflowStaticData('global');
const p=s.pendingTrade?.status==='pending'&&Date.now()<Number(s.pendingTrade.expiresAt||0)?s.pendingTrade:null;
return [{json:{
  ok:true,
  mode:'LIVE_ASSIST_PUBLISH_SAFE',
  market:{ok:!!s.lastMarket?.marketOk,pair:s.lastMarket?.pair||null,last:s.lastMarket?.last||null,universe:s.lastMarket?.universe||0},
  account:{ok:false,totalEq:null,balance:null,currency:'USDT',message:'Private OKX balance disabled in publish-safe build'},
  scanner:{state:s.lastMarket?.marketOk?'Active':'Standby',pair:s.lastMarket?.pair||null,signal:p?p.reason:'Waiting for valid signal'},
  strategy:{mode:'Live Assist Publish Safe',confirmationRequired:true,finalSubmit:'MANUAL_IN_OKX',approvalChannel:'JOHN_APP',minQuote:5,maxQuote:10},
  proposal:p,
  lastRun:{status:s.lastMarket?.marketOk?'Success':'Standby',at:s.lastMarket?.at||null}
}}];

const s=$getWorkflowStaticData('global');
const b=$json.body||$json;
const p=s.pendingTrade;
const id=String(b.proposalId||'');
const dec=String(b.decision||'').toLowerCase();
const no=(message,ok=false)=>[{json:{ok,approved:false,message}}];
if(!p||p.id!==id)return no('Proposal mismatch');
if(p.status!=='pending')return no('Proposal '+p.status);
if(Date.now()>=Number(p.expiresAt||0)){p.status='expired';return no('Proposal expired');}
if(dec==='reject'){p.status='rejected';return [{json:{ok:true,approved:false,status:'rejected'}}];}
if(dec!=='approve')return no('Decision must be approve or reject');
const amt=Number(p.amountQuote);
if(![5,10].includes(amt))return no('Risk guard blocked amount');
p.status='approved_for_handoff';
p.confirmedAt=Date.now();
const pair=String(p.pair||'BTC-USDT').toLowerCase();
return [{json:{ok:true,approved:true,status:'approved_for_manual_submit',pair:p.pair,side:p.side,amountQuote:p.amountQuote,entry:p.entry,stopLoss:p.stopLoss,takeProfit:p.takeProfit,openUrl:'https://www.okx.com/trade-spot/'+pair,message:'Aprobat. Verifică ordinul și apasă manual Submit în OKX.'}}];
